  }

  document.getElementById("analyzeBtn").addEventListener("click", analyze);
  document.getElementById("clearBtn").addEventListener("click", clearAll);
  document.getElementById("sampleBtn").addEventListener("click", loadSample);
  document.getElementById("copyBtn").addEventListener("click", function(){ copyText(checklist.textContent); });
  document.getElementById("copyBriefBtn").addEventListener("click", function(){ copyText(fullBrief()); });
  document.getElementById("downloadBtn").addEventListener("click", downloadBrief);

  [draft, relationship, tone, stakes].forEach(function(el){
    el.addEventListener("input", saveState);
    el.addEventListener("change", saveState);
  });

  loadState();
  if(draft.value.trim()) analyze();
})();
</script>
